@startuml

class House {
  + address : string
  + buildingMaterial : BuildingMaterial
}

class Basement {
  + name : string
  + size : float
}

class EarthBasement extends Basement {
  + humidityLevel : float
}

class ConcreteBasement extends Basement {}

class SemiDetachedHouse extends House {
  + hasOwnGarden : boolean
  + numberOfWindows : int
}

class Carport {
  + isDoubleCarport : boolean
  + hasFlatRoof : boolean
}

class Garage {
  + hasAutomaticGarageDoor : boolean
}

class Company {
  + name : string
  + address : string
}

class JobLog {
  + hours : float
  + agreedPrice : float
}

enum BuildingMaterial {
  WOOD
  BRICK
  CONCRETE
}

House "1" o-- "0..1" Basement
House "1" -- "*" JobLog
Company "1" -- "*" JobLog
SemiDetachedHouse "1" *-- "2" Carport
SemiDetachedHouse "1" *-- "1" Garage

@enduml

